#!/usr/bin/env python3
import hashlib, json, pathlib, shutil

ROOT=pathlib.Path(__file__).resolve().parent
OUT=ROOT/"site"
scenario=json.loads((ROOT/"scenario.json").read_text())
OUT.mkdir(exist_ok=True)
(OUT/"assets").mkdir(exist_ok=True)
shutil.copy2(ROOT/"assets/barbershop-hero.png",OUT/"assets/barbershop-hero.png")

shared='''<section class="services" id="services"><p class="kicker">Draft service menu — confirm before publishing</p><h2>Cut for the way you move.</h2><div class="service-grid"><article><b>Signature cut</b><span>Consultation, cut, finish</span></article><article><b>Fade or taper</b><span>Clean blend, sharp finish</span></article><article><b>Cut + beard detail</b><span>Balanced from every angle</span></article><article><b>Kids cut</b><span>Patient, comfortable service</span></article></div></section><section class="story"><p class="kicker">The chair is personal</p><h2>Craft, conversation, and your next clean look.</h2><p>This is a fictional proof. Community, experience, credentials, hours, services, and policies must be confirmed by the owner before customer use.</p></section><section class="booking" id="booking"><div><p class="kicker">Broward County, Florida</p><h2>Ready when you are.</h2><p>Choose a service, select a barber, and find a time. Phone booking remains available.</p></div><button data-book>Book an appointment</button></section><footer><b>Third Chair Studio</b><span>Concept proof · synthetic people and draft business information</span><a href="#top">Back to top</a></footer>'''

directions={
"safe":{"label":"SAFE","title":"Sharp looks.\nEasy booking.","lede":"A confident neighborhood barbershop experience built around trust, clarity, and the next appointment.","class":"safe","note":"Familiar, polished, and conversion-first."},
"wild":{"label":"WILD","title":"YOUR CUT.\nYOUR ENERGY.","lede":"Bold rhythm, expressive type, and a Broward pulse—without sacrificing the fastest path to the chair.","class":"wild","note":"Life Path 3 lens: expression, story, and room to explore."},
"omg":{"label":"OMG — I CAN'T BELIEVE THIS","title":"THE REVEAL\nSTARTS HERE.","lede":"A cinematic transformation story with a magnetic booking path and a premium, unexpected visual reveal.","class":"omg","note":"Showpiece direction: dramatic, memorable, still usable."}}

for key,d in directions.items():
    title=d["title"].replace("\n","<br>")
    page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Third Chair Studio — {d['label']}</title><link rel="stylesheet" href="styles.css"></head><body class="{d['class']}" id="top"><a class="skip" href="#main">Skip to content</a><nav aria-label="Primary"><a class="brand" href="index.html">THIRD CHAIR</a><div><a href="#services">Services</a><a href="#story">Our chair</a><a class="nav-cta" href="#booking">Book</a></div></nav><main id="main"><section class="hero"><img src="../assets/barbershop-hero.png" alt="Concept image of a Black barber giving a client a precision haircut in a contemporary shop"><div class="shade"></div><div class="hero-copy"><p class="kicker">{d['label']} DIRECTION · BROWARD COUNTY</p><h1>{title}</h1><p>{d['lede']}</p><div class="actions"><a class="primary" href="#booking">Book an appointment</a><a href="#services">View services</a></div><small>{d['note']} Optional numerology-inspired creative framing; not a personality claim.</small></div></section><section class="marquee" aria-label="Brand values"><span>PRECISION</span><span>CONFIDENCE</span><span>COMMUNITY</span><span>YOUR TIME</span></section>{shared}</main><dialog id="booking-dialog"><form method="dialog"><button class="close" aria-label="Close booking">×</button><p class="kicker">Test booking interaction</p><h2>Start your appointment</h2><label>Service<select><option>Choose a service</option><option>Signature cut</option><option>Fade or taper</option><option>Cut + beard detail</option></select></label><label>Barber preference<select><option>No preference</option><option>Choose later</option></select></label><button>Continue — test only</button><small>No appointment will be submitted.</small></form></dialog><script>document.querySelectorAll('[data-book]').forEach(b=>b.addEventListener('click',()=>document.querySelector('#booking-dialog').showModal()));</script></body></html>'''
    (OUT/f"{key}.html").write_text(page.replace("../assets/barbershop-hero.png","assets/barbershop-hero.png"))

review='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Third Chair — Proof Review</title><link rel="stylesheet" href="styles.css"></head><body class="review"><main><header><p class="kicker">FAMtastic local pilot · payment-safe</p><h1>Choose the direction that feels like you.</h1><p>Same facts and booking path. Three different creative intensities.</p></header><section class="proof-grid">__CARDS__</section><section class="decision"><div><p class="kicker">Selected proof</p><h2 id="selected-label">Nothing selected yet</h2><p id="state">Review all three directions before continuing.</p></div><button id="approve" disabled>Approve selected direction</button><button id="build" hidden>Build approved preview</button><button id="payment" hidden>Continue to payment</button></section><section class="ledger"><h2>Simulation ledger</h2><ol id="events"><li>intake_complete</li><li>proofs_generated</li><li>qa_passed</li><li>customer_review</li></ol></section></main><dialog id="payment-gate"><form method="dialog"><p class="kicker">Hard stop reached</p><h2>Payment required</h2><p>The approved preview is ready. This simulation stops before payment. No checkout session, card, charge, or order was created.</p><button>Close</button></form></dialog><script>let selected=null;const log=e=>{const li=document.createElement('li');li.textContent=e;events.append(li)};document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.select;document.querySelectorAll('.proof-card').forEach(c=>c.classList.toggle('chosen',c.dataset.id===selected));document.querySelector('#selected-label').textContent=b.dataset.label;document.querySelector('#state').textContent='Explicit selection recorded. Ready for simulated approval.';approve.disabled=false;log('proof_selected:'+selected)});approve.onclick=()=>{approve.hidden=true;build.hidden=false;document.querySelector('#state').textContent='Approved by Synthetic Test Customer. Artifact hash will be preserved.';log('approval_confirmed:'+selected)};build.onclick=()=>{build.hidden=true;payment.hidden=false;document.querySelector('#state').textContent='Approved preview built locally. Payment boundary is next.';log('build_authorized:'+selected);log('build_started:'+selected);log('payment_required')};payment.onclick=()=>document.querySelector('#payment-gate').showModal();</script></body></html>'''
cards=[]
for key,d in directions.items():
    cards.append(f'''<article class="proof-card" data-id="{key}"><iframe title="{d['label']} website proof" src="{key}.html"></iframe><div><p class="kicker">{d['label']}</p><h2>{d['note']}</h2><a href="{key}.html" target="_blank">Open full proof</a><button data-select="{key}" data-label="{d['label']}">Choose {d['label']}</button></div></article>''')
(OUT/"index.html").write_text(review.replace("__CARDS__","".join(cards)).replace("qa_passed","qa_baseline_passed"))

css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f4efe5;color:#171717;font-family:Arial,sans-serif}.skip{position:absolute;left:-9999px}.skip:focus{left:16px;top:16px;background:white;padding:12px;z-index:20}nav{position:absolute;z-index:5;width:100%;display:flex;justify-content:space-between;align-items:center;padding:22px 5vw;color:white}nav a{color:inherit;text-decoration:none;margin-left:24px;font-weight:700}.brand{letter-spacing:.18em;margin:0}.nav-cta{border:1px solid;padding:10px 18px}.hero{min-height:92vh;position:relative;display:flex;align-items:end;color:white;overflow:hidden}.hero>img,.shade{position:absolute;width:100%;height:100%;object-fit:cover}.shade{background:linear-gradient(90deg,rgba(0,0,0,.88),rgba(0,0,0,.1))}.hero-copy{z-index:2;max-width:760px;padding:14vh 6vw 9vh}.kicker{text-transform:uppercase;letter-spacing:.16em;font-weight:800;font-size:12px}.hero h1{font:900 clamp(58px,10vw,150px)/.78 Arial;margin:20px 0}.hero-copy>p:not(.kicker){font-size:20px;max-width:620px}.actions{display:flex;gap:16px;margin:35px 0}.actions a,button{padding:15px 20px;border:2px solid currentColor;background:transparent;color:inherit;text-decoration:none;font-weight:800;cursor:pointer}.primary{background:#f3c84b!important;color:#111!important;border-color:#f3c84b!important}.hero small{display:block;max-width:650px;opacity:.75}.marquee{display:flex;justify-content:space-around;gap:30px;padding:20px;overflow:hidden;background:#171717;color:white;font-weight:900}.services,.story,.booking{padding:90px 7vw}.services h2,.story h2,.booking h2{font:800 clamp(38px,6vw,80px)/.95 Georgia}.service-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.service-grid article{padding:26px;background:white;border-top:6px solid #171717;display:flex;flex-direction:column;gap:10px}.story{background:#171717;color:white;display:grid;grid-template-columns:1.2fr 1fr;gap:8vw}.booking{display:flex;justify-content:space-between;align-items:center;background:#f3c84b}.booking button{font-size:18px}footer{padding:30px 6vw;background:#111;color:white;display:flex;justify-content:space-between}footer a{color:white}dialog{max-width:520px;border:0;padding:34px;box-shadow:0 30px 100px #0008}dialog form{display:grid;gap:16px}label{display:grid;gap:7px}select{padding:12px}.close{position:absolute;right:10px;top:10px;border:0;font-size:25px}.wild{--accent:#ff3d81}.wild .primary,.wild .booking{background:var(--accent)!important;border-color:var(--accent)!important}.wild .hero h1{font-style:italic;transform:rotate(-2deg);text-shadow:6px 6px #4932ff}.wild .service-grid article:nth-child(even){transform:translateY(25px);background:#fbff43}.wild .marquee{background:#4932ff}.omg{--accent:#b9ff31;background:#080808;color:#eee}.omg .shade{background:radial-gradient(circle at 70% 40%,transparent 0 12%,#000c 60%)}.omg .hero h1{font-family:Georgia;font-weight:400;letter-spacing:-.07em;text-shadow:0 0 40px #b9ff3188}.omg .primary,.omg .booking{background:var(--accent)!important;color:#080808!important;border-color:var(--accent)!important}.omg .services{background:#080808}.omg .service-grid article{background:#171717;border-color:var(--accent)}.omg .story{background:linear-gradient(120deg,#270046,#080808)}.safe .hero h1{font-family:Georgia}.review main{max-width:1500px;margin:auto;padding:50px 30px}.review header{text-align:center;max-width:800px;margin:auto}.review header h1{font:700 clamp(42px,7vw,86px)/.95 Georgia}.proof-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:40px}.proof-card{background:white;border:4px solid transparent}.proof-card.chosen{border-color:#c65d36}.proof-card iframe{width:100%;height:420px;border:0;pointer-events:none}.proof-card>div{padding:20px}.proof-card button{display:block;margin-top:18px;background:#171717;color:white}.decision{display:flex;gap:18px;align-items:center;justify-content:space-between;margin-top:30px;padding:26px;background:#171717;color:white}.decision button{background:#f3c84b;color:#111}.decision button[disabled]{opacity:.4}.ledger{background:white;padding:24px;margin-top:20px}.ledger li{margin:8px}@media(max-width:800px){nav div a:not(.nav-cta){display:none}.hero{min-height:800px}.hero-copy{padding:140px 24px 70px}.hero h1{font-size:62px}.service-grid,.story,.proof-grid{grid-template-columns:1fr}.booking,.decision,footer{align-items:flex-start;flex-direction:column}.service-grid article:nth-child(even){transform:none}.proof-card iframe{height:520px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;animation:none!important;transition:none!important}}'''
(OUT/"styles.css").write_text(css)
manifest={"request_id":scenario["request_id"],"artifacts":{},"state":"proofs_generated"}
for file in OUT.iterdir():
    if file.is_file(): manifest["artifacts"][file.name]=hashlib.sha256(file.read_bytes()).hexdigest()
(OUT/"manifest.json").write_text(json.dumps(manifest,indent=2)+"\n")
print(OUT)
